/** @module local_glpisupport/tutorial */
define("local_glpisupport/tutorial", [], function() {
    'use strict';
    return {
        init: function(config) {
            var root = document.getElementById('glpisupport-tutorial');
            var main = document.getElementById('glpisupport-main-button');
            var floating = document.getElementById('glpisupport-floating-button');
            if (!root || !main || !floating || root.dataset.initialised === '1') {
                return;
            }
            root.dataset.initialised = '1';
            if (!config || !config.floating) {
                floating.hidden = true;
                return;
            }

            function setVisible(visible) {
                // Do not remove a keyboard-focused link before the user finishes using it.
                floating.hidden = !visible && document.activeElement !== floating;
            }
            function update() {
                // Only show once the main button has scrolled above the viewport.
                // A button below the fold at page load must not trigger the floating duplicate.
                setVisible(main.getBoundingClientRect().bottom <= 0);
            }
            floating.addEventListener('blur', update);
            if (window.IntersectionObserver) {
                var observer = new IntersectionObserver(update, {threshold: [0, 1]});
                observer.observe(main);
            } else {
                var pending = false;
                document.addEventListener('scroll', function() {
                    if (!pending) {
                        pending = true;
                        window.requestAnimationFrame(function() {
                            pending = false;
                            update();
                        });
                    }
                }, {passive: true, capture: true});
            }
            window.addEventListener('resize', update, {passive: true});
            update();
        }
    };
});

